test('dispatch without middleware updates state normally', () => {
  const reducer = (s: number, a: { type: string }) =>
    a.type === 'INC' ? s + 1 : s;
  const { result } = renderHook(() =>
    useReducerWithMiddleware(reducer, 0, [])
  );
  act(() => result.current[1]({ type: 'INC' }));
  expect(result.current[0]).toBe(1);
});

test('middleware can intercept and log actions', () => {
  const log: string[] = [];
  const mw: Middleware<number, { type: string }> = (s, a, next) => {
    log.push(a.type);
    next(a);
  };
  const reducer = (s: number, a: { type: string }) =>
    a.type === 'INC' ? s + 1 : s;
  const { result } = renderHook(() =>
    useReducerWithMiddleware(reducer, 0, [mw])
  );
  act(() => result.current[1]({ type: 'INC' }));
  expect(log).toEqual(['INC']);
  expect(result.current[0]).toBe(1);
});

test('middleware can block action by not calling next', () => {
  const blocker: Middleware<number, { type: string }> = (_s, _a, _next) => {};
  const reducer = (s: number, a: { type: string }) =>
    a.type === 'INC' ? s + 1 : s;
  const { result } = renderHook(() =>
    useReducerWithMiddleware(reducer, 0, [blocker])
  );
  act(() => result.current[1]({ type: 'INC' }));
  expect(result.current[0]).toBe(0);
});

test('multiple middlewares run in order', () => {
  const order: number[] = [];
  const mw1: Middleware<number, { type: string }> = (_s, _a, next) => { order.push(1); next(_a); };
  const mw2: Middleware<number, { type: string }> = (_s, _a, next) => { order.push(2); next(_a); };
  const reducer = (s: number, _: { type: string }) => s;
  const { result } = renderHook(() =>
    useReducerWithMiddleware(reducer, 0, [mw1, mw2])
  );
  act(() => result.current[1]({ type: 'X' }));
  expect(order).toEqual([1, 2]);
});

