test('middleware can modify action before passing to next', () => {
  const mw: Middleware<number, { type: string; value: number }> = (_s, a, next) => {
    next({ ...a, value: a.value * 10 });
  };
  const reducer = (s: number, a: { type: string; value: number }) =>
    a.type === 'SET' ? a.value : s;
  const { result } = renderHook(() =>
    useReducerWithMiddleware(reducer, 0, [mw])
  );
  act(() => result.current[1]({ type: 'SET', value: 5 }));
  expect(result.current[0]).toBe(50);
});

solution:
import { useReducer, useCallback, useRef } from 'react';

export type Middleware<S, A> = (
  state: S,
  action: A,
  next: (action: A) => void
) => void;

export function useReducerWithMiddleware<S, A>(
  reducer: (state: S, action: A) => S,
  initialState: S,
  middlewares: Middleware<S, A>[]
): [S, (action: A) => void] {
  const [state, coreDispatch] = useReducer(reducer, initialState);
  const stateRef = useRef(state);
  stateRef.current = state;

  const dispatch = useCallback((action: A) => {
    const chain = [...middlewares];
    const next = (index: number) => (act: A) => {
      if (index >= chain.length) {
        coreDispatch(act);
      } else {
        chain[index](stateRef.current, act, next(index + 1));
      }
    };
    next(0)(action);
  }, [middlewares, coreDispatch]);

  return [state, dispatch];
}
